#!/usr/bin/env node
/**
 * Stage 5 — Curriculum Dependency Resolution for
 * src/docs/projects/track-foundations/CONCEPT-GRAPH.md.
 *
 * A plain topological sort is necessary but not sufficient for ordering a
 * curriculum: a DAG admits many valid orders, and the graph alone can't say
 * which is pedagogically better. This script generates six artifacts, every
 * one *derived* from the graph, never hand-authored — regenerate by
 * re-running this script after any change to CONCEPT-GRAPH.md, never edit
 * the generated files directly:
 *
 *   CANONICAL-ORDER.md       - one deterministic topological order (Kahn's
 *                               algorithm, alphabetical-by-id tie-break) —
 *                               the "compiler order," not a lesson plan.
 *   DEPENDENCY-LEVELS.md     - layer(node) = 1 + max(layer of its required
 *                               prerequisites); leaves sit at layer 0.
 *   CONCEPT-CLUSTERS.md      - nodes introduced by the same lesson that are
 *                               directly connected to each other via
 *                               Required-prerequisites/Builds-toward edges —
 *                               candidate lesson-building-blocks for Stage 7.
 *                               Flags clusters too large to be one lesson,
 *                               without splitting them itself.
 *   CROSS-CLUSTER-EDGES.md   - a cluster-level dependency graph: which
 *                               clusters' concepts are required by which
 *                               other clusters' concepts. Stage 6 partitions
 *                               clusters into modules, not raw nodes — this
 *                               is the input that makes that possible.
 *   PRESSURE-REPORT.md       - Dependents + Prerequisites + Depth + Reuse,
 *                               ranked — a prioritization signal for which
 *                               concepts deserve the most careful teaching,
 *                               not a quality grade.
 *   CURRICULUM-VALIDATION.md - per-lesson Introduces/Requires check, with
 *                               violations classified into three severities:
 *                                 - Informational: Lesson 0 (an assumed-
 *                                   knowledge inventory, not sequential
 *                                   teaching) or a lesson explicitly
 *                                   annotated "(sighted only)"/"(assumed...)"
 *                                   in the graph itself. No action implied.
 *                                 - Curriculum warning: a genuine forward
 *                                   reference in track/'s lesson order — the
 *                                   concept graph says a lesson relies on
 *                                   something not introduced until later.
 *                                   track/ itself is immutable, but nothing
 *                                   requires the new foundation curriculum
 *                                   to reproduce that gap; treat the graph,
 *                                   not track/'s numbering, as authoritative
 *                                   for how the foundation material orders.
 *                                 - Structural error: a cycle or a dangling
 *                                   reference (from the shared validator) —
 *                                   these fail the build (nonzero exit).
 *
 * Usage:
 *   node scripts/concept-graph-resolve.mjs
 *   node scripts/concept-graph-resolve.mjs --file path/to/CONCEPT-GRAPH.md --out path/to/dir
 */

import { readFileSync, writeFileSync, mkdirSync } from 'fs'
import { resolve, dirname } from 'path'
import { fileURLToPath, pathToFileURL } from 'url'
import { parseNodes, buildGraph, parseIntroductionAnnotation } from './lib/concept-graph-parse.mjs'
import { validate, structuralErrors } from './lib/concept-graph-validate.mjs'

const __dirname = dirname(fileURLToPath(import.meta.url))
const root = resolve(__dirname, '..')

const args = process.argv.slice(2)
function flagValue(flag, fallback) {
  const i = args.indexOf(flag)
  return i >= 0 && args[i + 1] ? resolve(root, args[i + 1]) : fallback
}
const filePath = flagValue('--file', resolve(root, 'src/docs/projects/track-foundations/CONCEPT-GRAPH.md'))
const outDir = flagValue('--out', resolve(root, 'src/docs/projects/track-foundations/dependency-resolution'))

// A cluster larger than this is very unlikely to fit one instructional unit.
// This only flags for human review at Stage 6 — it never triggers an
// automatic split. Per-node-count splitting is explicitly rejected; large
// clusters should only be subdivided along weak dependency cuts.
export const OVERSIZED_CLUSTER_THRESHOLD = 10

const GENERATED_NOTICE =
  '> Generated by `scripts/concept-graph-resolve.mjs` from `CONCEPT-GRAPH.md`.\n' +
  '> Do not hand-edit — re-run the script after any change to the graph.\n'

// ---------------------------------------------------------------------------
// 1. Canonical topological order
// ---------------------------------------------------------------------------

function computeCanonicalOrder(byId) {
  const remaining = new Map([...byId.entries()].map(([id, n]) => [id, n.requiredPrereqs.length]))
  const readySet = new Set([...remaining.entries()].filter(([, deg]) => deg === 0).map(([id]) => id))
  const order = []
  while (readySet.size > 0) {
    const next = [...readySet].sort()[0]
    readySet.delete(next)
    order.push(next)
    for (const dep of byId.get(next).buildsToward) {
      if (!remaining.has(dep)) continue
      const deg = remaining.get(dep) - 1
      remaining.set(dep, deg)
      if (deg === 0) readySet.add(dep)
    }
  }
  return order
}

function mdCanonicalOrder(order, byId) {
  const lines = [
    '# Canonical Topological Order',
    '',
    GENERATED_NOTICE,
    'One valid, deterministic, reproducible ordering of all nodes such that',
    'every node appears strictly after every one of its `Required',
    "prerequisites` (Kahn's algorithm, alphabetical-by-id tie-break for",
    'determinism). This is the "compiler order" — mathematically valid, not',
    'yet pedagogically shaped. See `DEPENDENCY-LEVELS.md` for layering,',
    '`CONCEPT-CLUSTERS.md` for natural lesson-sized groupings, and',
    '`CROSS-CLUSTER-EDGES.md` for how those groupings depend on each other;',
    'those, not this raw order, should drive Stage 6/7 grouping decisions.',
    '',
  ]
  if (order.length !== byId.size) {
    lines.push(
      `**INCOMPLETE: ${order.length} of ${byId.size} nodes ordered — a cycle exists among the remaining ${byId.size - order.length}. See CURRICULUM-VALIDATION.md's Structural errors section.**`,
      ''
    )
  } else {
    lines.push(`${order.length} of ${order.length} nodes ordered — complete, no cycles.`, '')
  }
  order.forEach((id, i) => {
    const n = byId.get(id)
    lines.push(`${i + 1}. \`${id}\` — ${n.preferredName} (${n.category})`)
  })
  return lines.join('\n') + '\n'
}

// ---------------------------------------------------------------------------
// 2. Dependency levels
// ---------------------------------------------------------------------------

function computeLevels(byId) {
  const level = new Map()
  function levelOf(id, seen) {
    if (level.has(id)) return level.get(id)
    const node = byId.get(id)
    if (!node || node.requiredPrereqs.length === 0) {
      level.set(id, 0)
      return 0
    }
    if (seen.has(id)) return 0 // cycle guard; real cycles are reported as structural errors
    seen.add(id)
    let max = -1
    for (const dep of node.requiredPrereqs) {
      if (byId.has(dep)) max = Math.max(max, levelOf(dep, seen))
    }
    seen.delete(id)
    const result = max + 1
    level.set(id, result)
    return result
  }
  for (const id of byId.keys()) levelOf(id, new Set())
  return level
}

function mdDependencyLevels(levels, byId) {
  const byLevel = new Map()
  for (const [id, lvl] of levels.entries()) {
    if (!byLevel.has(lvl)) byLevel.set(lvl, [])
    byLevel.get(lvl).push(id)
  }
  const lines = [
    '# Dependency Levels',
    '',
    GENERATED_NOTICE,
    'Layer 0 holds every node with no `Required prerequisites`. Layer N holds',
    'every node whose deepest required-prerequisite chain is exactly N steps',
    'long — `layer(node) = 1 + max(layer(p) for p in Required prerequisites)`.',
    'Useful for visualization and for sanity-checking that early lessons stay',
    'in low layers.',
    '',
    `${byLevel.size} layers, ${byId.size} nodes total.`,
    '',
  ]
  const maxLevel = Math.max(...byLevel.keys())
  for (let lvl = 0; lvl <= maxLevel; lvl++) {
    const ids = (byLevel.get(lvl) || []).sort()
    lines.push(`## Layer ${lvl} (${ids.length} node${ids.length === 1 ? '' : 's'})`, '')
    for (const id of ids) {
      lines.push(`- \`${id}\` — ${byId.get(id).preferredName}`)
    }
    lines.push('')
  }
  return lines.join('\n')
}

// ---------------------------------------------------------------------------
// 3. Concept clusters
// ---------------------------------------------------------------------------

export function computeClusters(byId) {
  const byLesson = new Map()
  for (const node of byId.values()) {
    if (node.usedByLessons.length === 0) continue
    const introducedAt = node.usedByLessons[0]
    if (!byLesson.has(introducedAt)) byLesson.set(introducedAt, [])
    byLesson.get(introducedAt).push(node.id)
  }

  const clusters = []
  for (const [lesson, ids] of byLesson.entries()) {
    const idSet = new Set(ids)
    const adjacency = new Map(ids.map((id) => [id, new Set()]))
    for (const id of ids) {
      const node = byId.get(id)
      for (const dep of [...node.requiredPrereqs, ...node.buildsToward]) {
        if (idSet.has(dep) && dep !== id) {
          adjacency.get(id).add(dep)
          adjacency.get(dep).add(id)
        }
      }
    }
    const seen = new Set()
    for (const id of ids) {
      if (seen.has(id)) continue
      const component = []
      const queue = [id]
      seen.add(id)
      while (queue.length) {
        const cur = queue.shift()
        component.push(cur)
        for (const next of adjacency.get(cur)) {
          if (!seen.has(next)) {
            seen.add(next)
            queue.push(next)
          }
        }
      }
      if (component.length >= 2) {
        clusters.push({ lesson, members: component.sort() })
      }
    }
  }
  clusters.sort((a, b) => a.lesson - b.lesson || b.members.length - a.members.length)

  // Assign a deterministic, stable id per cluster: "L{lesson}{letter}" where
  // letter disambiguates multiple clusters sharing a lesson (a, b, c... in
  // the sort order above). Not a human name — Stage 7's job, not the
  // graph's — just a stable handle for CROSS-CLUSTER-EDGES.md to reference.
  const perLessonCount = new Map()
  for (const c of clusters) {
    const n = perLessonCount.get(c.lesson) || 0
    c.clusterId = `L${c.lesson}${String.fromCharCode(97 + n)}`
    perLessonCount.set(c.lesson, n + 1)
  }
  return clusters
}

function mdConceptClusters(clusters, byId) {
  const oversized = clusters.filter((c) => c.members.length > OVERSIZED_CLUSTER_THRESHOLD)
  const lines = [
    '# Concept Clusters',
    '',
    GENERATED_NOTICE,
    'Nodes introduced by the same `track/` lesson that are directly connected',
    'to each other via a `Required prerequisites`/`Builds toward` edge,',
    'grouped by connected component (size >= 2). These are mechanical',
    'candidate lesson-building-blocks for Stage 7 — a human name/label for',
    'each cluster is deliberately not generated here (that is a Stage 7',
    'grouping decision, not something derivable from the graph alone).',
    '',
    `${clusters.length} cluster(s) found.`,
    '',
  ]
  lines.push(
    '## Stage 6 partitioning rule',
    '',
    `Clusters larger than ${OVERSIZED_CLUSTER_THRESHOLD} nodes are flagged below for`,
    'human review, never split automatically by this script. The rule for',
    'any such split:',
    '',
    '> **Large connected components may be subdivided only along weak',
    '> dependency cuts, never by node count alone.**',
    '',
    'A weak cut is a point in the cluster where few edges cross — i.e. the',
    'two halves are each internally dense but only lightly connected to each',
    "other. That's a teaching-strata boundary (e.g. \"programming primitives\"",
    'vs. "object-oriented thinking" vs. "program execution" inside a large',
    'orientation-lesson cluster); a cut chosen purely to hit a target node',
    'count is not.',
    ''
  )
  if (oversized.length === 0) {
    lines.push('No clusters currently exceed the threshold.', '')
  } else {
    lines.push(`**${oversized.length} oversized cluster(s):**`, '')
    for (const c of oversized) {
      lines.push(`- \`${c.clusterId}\` (Lesson ${c.lesson}, ${c.members.length} nodes) — needs a weak-cut review before Stage 7.`)
    }
    lines.push('')
  }
  lines.push('---', '')
  for (const c of clusters) {
    lines.push(`## \`${c.clusterId}\` — Lesson ${c.lesson} (${c.members.length} nodes)`, '')
    for (const id of c.members) {
      lines.push(`- \`${id}\` — ${byId.get(id).preferredName}`)
    }
    lines.push('')
  }
  return lines.join('\n')
}

// ---------------------------------------------------------------------------
// 4. Cross-cluster edges
// ---------------------------------------------------------------------------

function computeCrossClusterEdges(byId, clusters) {
  const clusterOf = new Map()
  for (const c of clusters) {
    for (const id of c.members) clusterOf.set(id, c.clusterId)
  }

  // edgeKey "fromCluster->toCluster" -> Set of prereq concept ids that
  // triggered it (the "From" cluster's vocabulary the "To" cluster relies on).
  const edges = new Map()
  for (const node of byId.values()) {
    const toCluster = clusterOf.get(node.id)
    if (!toCluster) continue
    for (const prereq of node.requiredPrereqs) {
      const fromCluster = clusterOf.get(prereq)
      if (!fromCluster || fromCluster === toCluster) continue
      const key = `${fromCluster}->${toCluster}`
      if (!edges.has(key)) edges.set(key, new Set())
      edges.get(key).add(prereq)
    }
  }

  const rows = [...edges.entries()]
    .map(([key, concepts]) => {
      const [from, to] = key.split('->')
      return { from, to, concepts: [...concepts].sort() }
    })
    .sort((a, b) => a.from.localeCompare(b.from) || a.to.localeCompare(b.to))
  return rows
}

function mdCrossClusterEdges(edges, clusters, byId) {
  const clusterById = new Map(clusters.map((c) => [c.clusterId, c]))
  const lines = [
    '# Cross-Cluster Edges',
    '',
    GENERATED_NOTICE,
    'A cluster-level dependency graph: for every pair of clusters (see',
    '`CONCEPT-CLUSTERS.md`) where a node in one is a `Required prerequisite`',
    'of a node in the other, one row records which concepts carry that',
    'dependency. Edges to/from single-node (non-clustered) concepts are not',
    'included — those are already fully covered by `CANONICAL-ORDER.md` and',
    '`DEPENDENCY-LEVELS.md`; this artifact exists specifically to let Stage 6',
    'partition *clusters* into modules while minimizing cross-module',
    'prerequisite edges, preserving conceptual cohesion within each module.',
    '',
    '## Cluster legend',
    '',
    '| Cluster | Lesson | Size |',
    '| --- | ---: | ---: |',
  ]
  for (const c of clusters) {
    lines.push(`| \`${c.clusterId}\` | ${c.lesson} | ${c.members.length} |`)
  }
  lines.push('', `${edges.length} cross-cluster edge(s) found.`, '')
  lines.push('## Edges', '')
  lines.push('| From Cluster | To Cluster | Concepts |', '| --- | --- | --- |')
  for (const e of edges) {
    lines.push(`| \`${e.from}\` (L${clusterById.get(e.from).lesson}) | \`${e.to}\` (L${clusterById.get(e.to).lesson}) | ${e.concepts.map((c) => `\`${c}\``).join(', ')} |`)
  }
  return lines.join('\n') + '\n'
}

// ---------------------------------------------------------------------------
// 5. Pressure report
// ---------------------------------------------------------------------------

function computePressure(byId, levels) {
  return [...byId.values()]
    .map((n) => {
      const dependents = n.buildsToward.length
      const prerequisites = n.requiredPrereqs.length
      const depth = levels.get(n.id) ?? 0
      const reuse = Math.max(0, n.usedByLessons.length - 1)
      return {
        id: n.id,
        preferredName: n.preferredName,
        dependents,
        prerequisites,
        depth,
        reuse,
        pressure: dependents + prerequisites + depth + reuse,
      }
    })
    .sort((a, b) => b.pressure - a.pressure)
}

function mdPressureReport(pressure) {
  const lines = [
    '# Concept Pressure Report',
    '',
    GENERATED_NOTICE,
    'Pressure = Dependents (direct `Builds toward` count) + Prerequisites',
    '(direct `Required prerequisites` count) + Depth (dependency layer) +',
    'Reuse (times cited beyond its introducing lesson). Not a quality grade —',
    'a prioritization signal. High-pressure concepts are load-bearing: they',
    'deserve the most careful explanations, diagrams, and exercises, because',
    'the most other material rests on the learner actually getting them.',
    '',
    '| Rank | Concept | Pressure | Dependents | Prerequisites | Depth | Reuse |',
    '| ---: | --- | ---: | ---: | ---: | ---: | ---: |',
  ]
  pressure.forEach((p, i) => {
    lines.push(
      `| ${i + 1} | \`${p.id}\` (${p.preferredName}) | ${p.pressure} | ${p.dependents} | ${p.prerequisites} | ${p.depth} | ${p.reuse} |`
    )
  })
  return lines.join('\n') + '\n'
}

// ---------------------------------------------------------------------------
// 6. Curriculum validation (3-tier severity)
// ---------------------------------------------------------------------------

export function classifySeverity(violation, byId) {
  if (violation.lesson === 0) return 'informational'
  const node = byId.get(violation.node)
  const annotation = parseIntroductionAnnotation(node.usedByRaw, violation.lesson)
  if (annotation && /sighted only|assumed/i.test(annotation)) return 'informational'
  return 'curriculum-warning'
}

export function computeCurriculumValidation(byId) {
  const byLesson = new Map()
  for (const node of byId.values()) {
    if (node.usedByLessons.length === 0) continue
    const introducedAt = node.usedByLessons[0]
    if (!byLesson.has(introducedAt)) byLesson.set(introducedAt, [])
    byLesson.get(introducedAt).push(node.id)
  }
  const lessons = [...byLesson.keys()].sort((a, b) => a - b)
  const perLesson = []
  const violations = []
  for (const lesson of lessons) {
    const introduces = byLesson.get(lesson).sort()
    const requiresMap = new Map()
    const lessonViolations = []
    for (const id of introduces) {
      const node = byId.get(id)
      for (const prereq of node.requiredPrereqs) {
        const prereqNode = byId.get(prereq)
        const prereqIntroducedAt = prereqNode?.usedByLessons[0]
        requiresMap.set(prereq, prereqIntroducedAt)
        if (prereqIntroducedAt !== undefined && prereqIntroducedAt > lesson) {
          const violation = { lesson, node: id, prereq, prereqIntroducedAt }
          violation.severity = classifySeverity(violation, byId)
          lessonViolations.push(violation)
          violations.push(violation)
        }
      }
    }
    perLesson.push({
      lesson,
      introduces,
      requires: [...requiresMap.entries()]
        .sort(([a], [b]) => (a < b ? -1 : 1))
        .map(([id, introducedAt]) => ({ id, introducedAt, ok: introducedAt <= lesson })),
      violations: lessonViolations,
    })
  }
  return { perLesson, violations }
}

function mdCurriculumValidation({ perLesson, violations }, structural, byId) {
  const informational = violations.filter((v) => v.severity === 'informational')
  const warnings = violations.filter((v) => v.severity === 'curriculum-warning')

  const lines = [
    '# Curriculum Validation',
    '',
    GENERATED_NOTICE,
    'For every `track/` lesson, checks that every `Required prerequisite` of',
    'a node that lesson *introduces* was itself introduced at or before that',
    'same lesson. Findings are classified into three severities:',
    '',
    '- **Structural error** — a cycle or a dangling reference (from the',
    '  shared graph validator). Fails the build.',
    '- **Curriculum warning** — a genuine forward reference in `track/`\'s',
    '  lesson order: the graph says a lesson relies on something not',
    '  introduced until later. `track/` itself is immutable and is not being',
    '  "fixed" — but the new foundation curriculum is not obligated to',
    '  reproduce this gap. Treat the graph, not `track/`\'s original lesson',
    '  numbering, as authoritative for how foundation material gets ordered.',
    '  Review during Stage 6/7 lesson grouping.',
    '- **Informational** — a historical quirk: Lesson 0 (`track/`\'s own',
    '  assumed-knowledge inventory, not sequential teaching) or a lesson',
    '  explicitly annotated `(sighted only)`/`(assumed...)` in the graph',
    '  itself. No action implied.',
    '',
  ]

  lines.push(
    `## Structural errors (${structural.length})`,
    ''
  )
  if (structural.length === 0) {
    lines.push('None. (Also checked by `concept-graph-report.mjs` on every run.)', '')
  } else {
    for (const s of structural) lines.push(`- ${s}`)
    lines.push('')
  }

  lines.push(`## Curriculum warnings (${warnings.length})`, '')
  if (warnings.length === 0) {
    lines.push('None.', '')
  } else {
    for (const v of warnings) {
      lines.push(
        `- Lesson ${v.lesson} introduces \`${v.node}\`, which requires \`${v.prereq}\` — not introduced until Lesson ${v.prereqIntroducedAt}.`
      )
    }
    lines.push('')
  }

  lines.push(`## Informational (${informational.length})`, '')
  if (informational.length === 0) {
    lines.push('None.', '')
  } else {
    for (const v of informational) {
      lines.push(
        `- Lesson ${v.lesson} introduces \`${v.node}\`, which requires \`${v.prereq}\` — not introduced until Lesson ${v.prereqIntroducedAt}. (historical quirk, no action implied)`
      )
    }
    lines.push('')
  }

  lines.push('---', '', '## Per-lesson detail', '')
  for (const l of perLesson) {
    lines.push(`### Lesson ${l.lesson}`, '')
    lines.push('Introduces:')
    if (l.introduces.length === 0) {
      lines.push('- (none)')
    } else {
      for (const id of l.introduces) lines.push(`- \`${id}\` — ${byId.get(id).preferredName}`)
    }
    lines.push('', 'Requires:')
    if (l.requires.length === 0) {
      lines.push('- (none — no prerequisites outside this lesson)')
    } else {
      for (const r of l.requires) {
        const mark = r.ok ? '✓' : `✗ (introduced Lesson ${r.introducedAt})`
        lines.push(`- \`${r.id}\` ${mark}`)
      }
    }
    lines.push('', 'Uses before introduction:')
    if (l.violations.length === 0) {
      lines.push('- NONE')
    } else {
      for (const v of l.violations) {
        lines.push(`- \`${v.node}\` uses \`${v.prereq}\`, introduced Lesson ${v.prereqIntroducedAt} — **${v.severity}**`)
      }
    }
    lines.push('')
  }
  return lines.join('\n')
}

// ---------------------------------------------------------------------------

function main() {
  const text = readFileSync(filePath, 'utf8')
  const nodes = parseNodes(text)
  const byId = buildGraph(nodes)

  console.log(`Parsed ${nodes.length} node headings from ${filePath}`)

  const structural = structuralErrors(validate(byId))
  const order = computeCanonicalOrder(byId)
  const levels = computeLevels(byId)
  const clusters = computeClusters(byId)
  const crossClusterEdges = computeCrossClusterEdges(byId, clusters)
  const pressure = computePressure(byId, levels)
  const validation = computeCurriculumValidation(byId)

  mkdirSync(outDir, { recursive: true })

  const files = {
    'CANONICAL-ORDER.md': mdCanonicalOrder(order, byId),
    'DEPENDENCY-LEVELS.md': mdDependencyLevels(levels, byId),
    'CONCEPT-CLUSTERS.md': mdConceptClusters(clusters, byId),
    'CROSS-CLUSTER-EDGES.md': mdCrossClusterEdges(crossClusterEdges, clusters, byId),
    'PRESSURE-REPORT.md': mdPressureReport(pressure),
    'CURRICULUM-VALIDATION.md': mdCurriculumValidation(validation, structural, byId),
  }
  for (const [name, content] of Object.entries(files)) {
    writeFileSync(resolve(outDir, name), content, 'utf8')
  }

  const warnings = validation.violations.filter((v) => v.severity === 'curriculum-warning')
  const informational = validation.violations.filter((v) => v.severity === 'informational')
  const oversizedClusters = clusters.filter((c) => c.members.length > OVERSIZED_CLUSTER_THRESHOLD)

  console.log(`\nWrote 6 artifacts to ${outDir}:`)
  console.log(`  CANONICAL-ORDER.md       - ${order.length}/${byId.size} nodes ordered${order.length !== byId.size ? ' (INCOMPLETE - cycle present)' : ''}`)
  console.log(`  DEPENDENCY-LEVELS.md     - ${Math.max(...levels.values()) + 1} layers`)
  console.log(`  CONCEPT-CLUSTERS.md      - ${clusters.length} clusters, ${oversizedClusters.length} oversized (>${OVERSIZED_CLUSTER_THRESHOLD} nodes)`)
  console.log(`  CROSS-CLUSTER-EDGES.md   - ${crossClusterEdges.length} cross-cluster edges`)
  console.log(`  PRESSURE-REPORT.md       - top: ${pressure[0].id} (pressure ${pressure[0].pressure})`)
  console.log(`  CURRICULUM-VALIDATION.md - ${structural.length} structural error(s), ${warnings.length} curriculum warning(s), ${informational.length} informational`)

  process.exitCode = structural.length > 0 || order.length !== byId.size ? 1 : 0
}

// Only run when this file is the invoked entry point, not when its compute
// functions are imported (e.g. by scripts/concept-graph-audit.mjs) — an
// import must never trigger a full re-run and file-write as a side effect.
if (import.meta.url === pathToFileURL(process.argv[1]).href) {
  main()
}
